def copy_figures(apps, schema_editor):
    """The item's one safety stock and maximum become a line for each stock branch."""
    Item = apps.get_model("core", "Item")
    Branch = apps.get_model("core", "Branch")
    ItemPlan = apps.get_model("core", "ItemPlan")
    branches = list(Branch.objects.filter(is_active=True, no_stock=False))
    lines = []
    items = Item.objects.filter(maintain_stock=True).exclude(
        safety_stock_qty__isnull=True, max_stock_qty__isnull=True
    )
    for item in items:
        fulfilment = item.default_request_type or "purchase"
        for branch in branches:
            lines.append(
                ItemPlan(
                    item=item,
                    branch=branch,
                    fulfilment=fulfilment,
                    safety_qty=item.safety_stock_qty or 0,
                    order_up_to=item.max_stock_qty,
                )
            )
    ItemPlan.objects.bulk_create(lines)


